</div>

<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.166.1/build/three.module.js';
import { OrbitControls } from 'https://cdn.jsdelivr.net/npm/three@0.166.1/examples/jsm/controls/OrbitControls.js';

// ==================== קונפיגורציה ====================
const CONFIG = {
 humanHeight: 3,
 humanSpeedBase: 0.02,
 spawnInterval: 2000,
 bulletSpeed: 0.25,
 maxLives: 3,
 difficultyRamp: 0.95,
 sceneWidth: window.innerWidth,
 sceneHeight: window.innerHeight - 80
};

// ==================== משתנים גלובליים ====================
let scene, camera, renderer, raycaster;
let humans = [], bullets = [];
let score = 0, lives = CONFIG.maxLives;
let lastSpawn = 0, spawnTimer = CONFIG.spawnInterval;
let gameOver = false;

// ==================== אתחול Three.js ====================
function initThree() {
 scene = new THREE.Scene();
 scene.background = new THREE.Color(0xf0f4f8);

 camera = new THREE.PerspectiveCamera(60, CONFIG.sceneWidth / CONFIG.sceneHeight, 0.1, 100);
 camera.position.set(0, 5, 12);
 camera.lookAt(0, 0, 0);

 renderer = new THREE.WebGLRenderer({ antialias: true });
 renderer.setSize(CONFIG.sceneWidth, CONFIG.sceneHeight);
 document.body.appendChild(renderer.domElement);

 const ambient = new THREE.AmbientLight(0xffffff, 0.7);
 scene.add(ambient);
 const dirLight = new THREE.DirectionalLight(0xffffff, 0.6);
 dirLight.position.set(5, 10, 7);
 scene.add(dirLight);

 const grid = new THREE.GridHelper(30, 30, 0xcccccc, 0xeeeeee);
 scene.add(grid);

 raycaster = new THREE.Raycaster();

 const controls = new OrbitControls(camera, renderer.domElement);
 controls.enablePan = false;
 controls.enableZoom = false;
}

// ==================== מחלקת אדם ====================
class Human {
 constructor() {
 // גוף מרכזי (קובייה)
 const bodyGeo = new THREE.BoxGeometry(1, CONFIG.humanHeight * 0.6, 0.5);
 const bodyMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
 this.body = new THREE.Mesh(bodyGeo, bodyMat);
 this.body.position.y = CONFIG.humanHeight / 2;

 // רגליים (שתי קוביות)
 const legGeo = new THREE.BoxGeometry(0.3, CONFIG.humanHeight * 0.4, 0.3);
 const legMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
 this.leftLeg = new THREE.Mesh(legGeo, legMat);
 this.rightLeg = this.leftLeg.clone();
 this.leftLeg.position.set(-0.25, CONFIG.humanHeight * 0.2, 0);
 this.rightLeg.position.set(0.25, CONFIG.humanHeight * 0.2, 0);

 // ידיים (קוביות דקות)
 const armGeo = new THREE.BoxGeometry(0.2, CONFIG.humanHeight * 0.5, 0.2);
 const armMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
 this.leftArm = new THREE.Mesh(armGeo, armMat);
 this.rightArm = this.leftArm.clone();
 this.leftArm.position.set(-0.7, CONFIG.humanHeight * 0.6, 0);
 this.rightArm.position.set(0.7, CONFIG.humanHeight * 0.6, 0);

 // רובה (קובייה ארוכה)
 const gunGeo = new THREE.BoxGeometry(0.2, 0.2, 2);
 const gunMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
 this.gun = new THREE.Mesh(gunGeo, gunMat);
 // מחזיקים את הרובה ביד ימין
 this.gun.position.set(0.9, CONFIG.humanHeight * 0.6, -0.5);
 this.gun.rotation.y = Math.PI / 2;

 // סרט ירוק על הראש
 const bandGeo = new THREE.BoxGeometry(0.8, 0.15, 0.2);
 const bandMat = new THREE.MeshStandardMaterial({ color: 0x2ecc71 });
 this.band = new THREE.Mesh(bandGeo, bandMat);
 this.band.position.set(0, CONFIG.humanHeight * 0.9, 0);

 // קבוצה ראשית
 this.group = new THREE.Group();
 this.group.add(this.body, this.leftLeg, this.rightLeg, this.leftArm, this.rightArm, this.gun, this.band);
 this.group.position.set(
 (Math.random() - 0.5) * 20,
 0,
 -30
 );

 scene.add(this.group);
 this.speed = CONFIG.humanSpeedBase + Math.random() * 0.01;
 this.hit = false;
 }

 update(delta) {
 this.group.position.z += this.speed * delta;
 if (this.group.position.z > 5) this.hit = true;
 }

 dispose() {
 const disposeMesh = (m) => { m.geometry.dispose(); m.material.dispose(); };
 [this.body, this.leftLeg, this.rightLeg, this.leftArm, this.rightArm, this.gun, this.band].forEach(disposeMesh);
 scene.remove(this.group);
 }
}

// ==================== כדור ====================
class Bullet {
 constructor(x, y) {
 const geo = new THREE.SphereGeometry(0.2, 12, 12);
 const mat = new THREE.MeshStandardMaterial({ color: 0xe74c3c });
 this.mesh = new THREE.Mesh(geo, mat);
 this.mesh.position.set(x, y, 0);
 scene.add(this.mesh);
 }
 update(delta) {
 this.mesh.position.z -= CONFIG.bulletSpeed * delta;
 }
 dispose() {
 this.mesh.geometry.dispose();
 this.mesh.material.dispose();
 scene.remove(this.mesh);
 }
}

// ==================== אירועי משחק ====================
function onCanvasClick(event) {
 if (gameOver) return;
 const rect = renderer.domElement.getBoundingClientRect();
 const mouse = new THREE.Vector2(
 ((event.clientX - rect.left) / rect.width) * 2 - 1,
 -((event.clientY - rect.top) / rect.height) * 2 + 1
 );
 raycaster.setFromCamera(mouse, camera);
 const dir = raycaster.ray.direction.clone().multiplyScalar(100);
 const pos = raycaster.ray.origin.clone();
 bullets.push(new Bullet(pos.x, pos.y));
}

function spawnHuman() {
 humans.push(new Human());
}

function checkCollisions() {
 bullets.forEach((b, bi) => {
 humans.forEach((h, hi) => {
 const dist = b.mesh.position.distanceTo(h.group.position);
 if (dist < 0.5 + CONFIG.humanHeight * 0.3) {
 // פגיעה
 score++;
 document.getElementById('score').textContent = score;
 if (score % 10 === 0) spawnTimer *= CONFIG.difficultyRamp;

 // ניקוי
 h.dispose();
 humans.splice(hi, 1);
 b.dispose();
 bullets.splice(bi, 1);
 }
 });
 });
}

function handleLives() {
 humans = humans.filter(h => {
 if (h.hit) {
 lives--;
 document.getElementById('lives').textContent = lives;
 if (lives <= 0) endGame();
 h.dispose();
 return false;
 }
 return true;
 });
}

function endGame() {
 gameOver = true;
 document.getElementById('gameOverScreen').style.visibility = 'visible';
}

function resetGame() {
 score = 0;
 lives = CONFIG.maxLives;
 document.getElementById('score').textContent = score;
 document.getElementById('lives').textContent = lives;
 humans.forEach(h => h.dispose());
 bullets.forEach(b => b.dispose());
 humans = [];
 bullets = [];
 spawnTimer = CONFIG.spawnInterval;
 lastSpawn = 0;
 gameOver = false;
 document.getElementById('gameOverScreen').style.visibility = 'hidden';
}

// ==================== לולאת רינדור ====================
let lastTime = 0;
function animate(timestamp) {
 const delta = (timestamp - lastTime) || 16;
 lastTime = timestamp;

 if (!gameOver && timestamp - lastSpawn > spawnTimer) {
 spawnHuman();
 lastSpawn = timestamp;
 }

 humans.forEach(h => h.update(delta));
 bullets.forEach(b => b.update(delta));

 // ניקוי כדורים שעזבו את המרחב
 bullets = bullets.filter(b => {
 if (b.mesh.position.z < -30) {
 b.dispose();
 return false;
 }
 return true;
 });

 checkCollisions();
 handleLives();

 renderer.render(scene, camera);
 if (!gameOver) requestAnimationFrame(animate);
}

// ==================== הפעלת המשחק ====================
function start() {
 initThree();
 renderer.domElement.addEventListener('click', onCanvasClick);
 document.getElementById('restartBtn').addEventListener('click', resetGame);
 requestAnimationFrame(animate);
}

window.addEventListener('load', start);
window.addEventListener('resize', () => {
 CONFIG.sceneWidth = window.innerWidth;
 CONFIG.sceneHeight = window.innerHeight - 80;
 camera.aspect = CONFIG.sceneWidth / CONFIG.sceneHeight;
 camera.updateProjectionMatrix();
 renderer.setSize(CONFIG.sceneWidth, CONFIG.sceneHeight);
});
</script>
</body>
</html>
```

**שינויים מרכזיים** 
- **מחלקת `Human`**: בנייה של גוף אדם בעזרת קוביות (גוף, רגליים, ידיים), רובה (קובייה ארוכה) וסרט ירוק על הראש. 
- כל הלוגיקה של תנועה, פגיעה, ניקוד וקושי נשמרת ללא שינוי. 
- משאבים מנוקים (`dispose`) כדי למנוע דליפות זיכרון. 

**הרחבות אפשריות** 
- להחליף את המודלים הפשוטים במודלים של GLTF/GLB של דמויות ריאליסטיות. 
- להוסיף אנימציות הליכה/ירי בעזרת `Skeleton` ו‑`AnimationMixer`. 
- להציג אפקט פיצוץ חלקיקי כאשר הרובה פוגע.
